from django.utils.crypto import salted_hmac

class DuckUser:
    pk = 1
    password = "pw"
    is_active = True
    def get_session_auth_hash(self):
        return salted_hmac("duck", self.password, algorithm="sha256").hexdigest()

class Backend:
    def get_user(self, user_id):
        return DuckUser()
EOF
